import Foundation
import SwiftData

@MainActor
public final class Dependencies {

    public let appConfiguration: AppConfig
    public let identityService: IdentityServiceSupporting
    public let persistenceDataSource: PersistenceDataSourceSupporting
    public let identificationService: IdentificationServiceSupporting
    public let diagnosisService: DiagnosisServiceSupporting
    public let gardenService: GardenServiceSupporting
    public let careService: CareServiceSupporting
    public let careNoteService: CareNoteServiceSupporting
    let subscriptionService: SubscriptionServiceSupporting
    public let cameraService: CameraServiceSupporting
    public let detectionService: DetectionServiceSupporting
    public let depthDataService: DepthDataServiceSupporting
    public let lightMeterService: LightMeterServiceSupporting
    public let notificationService: NotificationServiceSupporting
    public let networkMonitorService: NetworkMonitorServiceSupporting
    let weatherService: WeatherServiceSupporting
    let postsFeedService: PostsFeedServiceSupporting
    public let entitlementSource: EntitlementSourceSupporting
    public let communityWaitlistStorage: CommunityWaitlistStorageSupporting
    public let stateTransitions: any StateTransitionHandling
    public let reviewRequester: any ReviewRequesterSupporting
    public let ratingPromptCoordinator: any RatingPromptCoordinatorSupporting
    public let onboardingProfileStore: OnboardingProfileStoreSupporting
    public let specialOfferStorage: SpecialOfferStorageSupporting

    // MARK: - Repositories (local persistence layer)

    public let plantRepository: PlantRepositorySupporting
    public let careLogRepository: CareLogRepositorySupporting
    public let careScheduleRepository: CareScheduleRepositorySupporting
    public let careNoteRepository: CareNoteRepositorySupporting

    /// Designated initializer: assigns every service explicitly. Use the
    /// `init(modelContainer:appConfiguration:)` live factory in the app and
    /// `Dependencies.mock()` in previews and snapshot tests.
    // swiftlint:disable:next function_body_length
    init(
        appConfiguration: AppConfig,
        identityService: IdentityServiceSupporting,
        persistenceDataSource: PersistenceDataSourceSupporting,
        identificationService: IdentificationServiceSupporting,
        diagnosisService: DiagnosisServiceSupporting,
        gardenService: GardenServiceSupporting,
        careService: CareServiceSupporting,
        careNoteService: CareNoteServiceSupporting,
        subscriptionService: SubscriptionServiceSupporting,
        cameraService: CameraServiceSupporting,
        detectionService: DetectionServiceSupporting,
        depthDataService: DepthDataServiceSupporting,
        lightMeterService: LightMeterServiceSupporting,
        notificationService: NotificationServiceSupporting,
        networkMonitorService: NetworkMonitorServiceSupporting,
        weatherService: WeatherServiceSupporting,
        postsFeedService: PostsFeedServiceSupporting,
        entitlementSource: EntitlementSourceSupporting,
        communityWaitlistStorage: CommunityWaitlistStorageSupporting,
        stateTransitions: any StateTransitionHandling,
        reviewRequester: any ReviewRequesterSupporting,
        ratingPromptCoordinator: any RatingPromptCoordinatorSupporting,
        onboardingProfileStore: OnboardingProfileStoreSupporting,
        specialOfferStorage: SpecialOfferStorageSupporting,
        plantRepository: PlantRepositorySupporting,
        careLogRepository: CareLogRepositorySupporting,
        careScheduleRepository: CareScheduleRepositorySupporting,
        careNoteRepository: CareNoteRepositorySupporting
    ) {
        self.appConfiguration = appConfiguration
        self.identityService = identityService
        self.persistenceDataSource = persistenceDataSource
        self.identificationService = identificationService
        self.diagnosisService = diagnosisService
        self.gardenService = gardenService
        self.careService = careService
        self.careNoteService = careNoteService
        self.subscriptionService = subscriptionService
        self.cameraService = cameraService
        self.detectionService = detectionService
        self.depthDataService = depthDataService
        self.lightMeterService = lightMeterService
        self.notificationService = notificationService
        self.networkMonitorService = networkMonitorService
        self.weatherService = weatherService
        self.postsFeedService = postsFeedService
        self.entitlementSource = entitlementSource
        self.communityWaitlistStorage = communityWaitlistStorage
        self.stateTransitions = stateTransitions
        self.reviewRequester = reviewRequester
        self.ratingPromptCoordinator = ratingPromptCoordinator
        self.onboardingProfileStore = onboardingProfileStore
        self.specialOfferStorage = specialOfferStorage
        self.plantRepository = plantRepository
        self.careLogRepository = careLogRepository
        self.careScheduleRepository = careScheduleRepository
        self.careNoteRepository = careNoteRepository
    }

    /// Live factory: wires the full production service graph.
    // swiftlint:disable:next function_body_length
    public convenience init(modelContainer: ModelContainer, appConfiguration: AppConfig) {

        let identityService = FirebaseIdentityService()

        let persistence = PersistenceDataSource(modelContainer: modelContainer)

        let tokenProvider: @Sendable () async throws -> String = { [identityService] in
            try await identityService.idToken()
        }

        let apiClient = APIClient(baseURL: appConfiguration.backendBaseURL, tokenProvider: tokenProvider)
        let identificationService = IdentificationService(apiClient: apiClient)
        let diagnosisService = DiagnosisService(apiClient: apiClient)
        let communityWaitlistStorage = UserDefaultsCommunityWaitlistStorage()

        // MARK: Repositories (local persistence layer)

        let plantRepo = PlantRepository(persistence: persistence)
        let careLogRepo = CareLogRepository(persistence: persistence)
        let careScheduleRepo = CareScheduleRepository(persistence: persistence)
        let careNoteRepo = CareNoteRepository(persistence: persistence)

        // MARK: Services (now using repositories)

        let notification = NotificationService()

        let careService = CareService(
            careScheduleRepository: careScheduleRepo,
            careLogRepository: careLogRepo,
            plantRepository: plantRepo,
            notificationService: notification
        )
        // After `careService`, which it needs: removing a plant from the Garden has to
        // retire that plant's care and cancel its pending reminders.
        let gardenService = GardenService(plantRepository: plantRepo, careService: careService)
        let careNoteService = CareNoteService(careNoteRepository: careNoteRepo)

        var subscriptionService: SubscriptionServiceSupporting = appConfiguration.hasRevenueCatConfiguration
            ? SubscriptionService()
            : MockSubscriptionService()

        #if DEBUG
        // The paywall catalog picker in the debug menu, wrapping whatever the line above chose.
        // Release never sees this: `DebugCatalogSubscriptionService` is itself declared inside
        // `#if DEBUG` — the same containment `DebugMenuLauncher` uses — so neither the decorator
        // nor the fixture prices it serves can compile into a Release binary.
        //
        // Must happen before `LiveEntitlementSource` and `LiveStateTransitionHandler` are built
        // below, or restore and entitlement would flow through a different object than the
        // paywalls do.
        subscriptionService = DebugCatalogSubscriptionService(wrapping: subscriptionService)
        #endif

        let detectionService = DetectionService()

        #if targetEnvironment(simulator)
        let cameraService: CameraServiceSupporting = MockCameraService()
        let depthDataService: DepthDataServiceSupporting = MockDepthDataService()
        // No `AVCaptureDevice` on the simulator, so the real meter would report nothing at all.
        let lightMeterService: LightMeterServiceSupporting = MockLightMeterService()
        #else
        let cameraService: CameraServiceSupporting = CameraService()
        let depthDataService: DepthDataServiceSupporting = DepthDataService()
        let lightMeterService: LightMeterServiceSupporting = LightMeterService(cameraService: cameraService)
        #endif

        let networkMonitor = NetworkMonitorService()
        networkMonitor.startMonitoring()

        let entitlement = LiveEntitlementSource(subscriptionService: subscriptionService)

        let stateTransitions = LiveStateTransitionHandler(
            subscriptionService: subscriptionService,
            entitlementSource: entitlement
        )

        let reviewRequester = LiveReviewRequester()
        let ratingStorage = UserDefaultsRatingPromptStorage()
        let ratingPromptCoordinator = LiveRatingPromptCoordinator(
            storage: ratingStorage,
            reviewRequester: reviewRequester
        )

        let onboardingProfileStore = UserDefaultsOnboardingProfileStore()
        let specialOfferStorage = UserDefaultsSpecialOfferStorage()

        self.init(
            appConfiguration: appConfiguration,
            identityService: identityService,
            persistenceDataSource: persistence,
            identificationService: identificationService,
            diagnosisService: diagnosisService,
            gardenService: gardenService,
            careService: careService,
            careNoteService: careNoteService,
            subscriptionService: subscriptionService,
            cameraService: cameraService,
            detectionService: detectionService,
            depthDataService: depthDataService,
            lightMeterService: lightMeterService,
            notificationService: notification,
            networkMonitorService: networkMonitor,
            weatherService: LiveWeatherService(),
            postsFeedService: LivePostsFeedService(
                feedURL: appConfiguration.backendBaseURL.appending(path: "posts")
            ),
            entitlementSource: entitlement,
            communityWaitlistStorage: communityWaitlistStorage,
            stateTransitions: stateTransitions,
            reviewRequester: reviewRequester,
            ratingPromptCoordinator: ratingPromptCoordinator,
            onboardingProfileStore: onboardingProfileStore,
            specialOfferStorage: specialOfferStorage,
            plantRepository: plantRepo,
            careLogRepository: careLogRepo,
            careScheduleRepository: careScheduleRepo,
            careNoteRepository: careNoteRepo
        )
    }
}

