import Foundation

/// Configuration for the paywall screen, provided by `AppConfig`.
public struct PaywallConfig: Sendable {
    /// Premium tier name shown in the Settings subscription card (e.g., "Save My Cactus Pro").
    public let premiumTierName: String
    /// Headline on the upgrade card in Settings. The same line the full paywall leads with, so
    /// the card reads as a smaller view of the same offer rather than a second, different pitch.
    public let upgradeCtaTitle: String
    /// Label on the upgrade card's button and the paywall's.
    public let ctaLabel: String
    /// The RevenueCat offering the limited time offer screen sells.
    ///
    /// A dashboard that publishes no such offering falls back to the current one rather than
    /// rendering an empty paywall with a dead button — the rule lives in
    /// `SubscriptionService.catalog(_:)`, see `PaywallOfferingSelector`.
    public let specialOfferOfferingIdentifier: String
    /// How long the limited time window lasts, from the moment the offer banner is first shown.
    ///
    /// Read only when a deadline is *created*. The deadline itself is persisted as an absolute
    /// date, so shipping a different window never moves a live user's clock.
    public let specialOfferWindow: TimeInterval

    public init(
        premiumTierName: String,
        upgradeCtaTitle: String = String(localized: "Let's get to work.", comment: "Headline on the Settings upgrade card and the paywall"),
        ctaLabel: String = String(localized: "Start free trial", comment: "Paywall call to action button label"),
        specialOfferOfferingIdentifier: String = "special_offer",
        specialOfferWindow: TimeInterval = 24 * 60 * 60
    ) {
        self.premiumTierName = premiumTierName
        self.upgradeCtaTitle = upgradeCtaTitle
        self.ctaLabel = ctaLabel
        self.specialOfferOfferingIdentifier = specialOfferOfferingIdentifier
        self.specialOfferWindow = specialOfferWindow
    }
}

