import Foundation
import RevenueCat

// Where RevenueCat becomes the app's own values, and the only place it does.
//
// Everything downstream — both paywalls, the Settings payramp, both view models — reads
// `PaywallCatalog` and `PaywallPlan`. That is what makes them mockable: `StoreProduct` cannot be
// constructed without a real StoreKit product, so any type that reaches one cannot be faked, and a
// screen that reads one cannot be drawn before the dashboard is configured.

extension PaywallCatalog {

    /// Reads a whole offering, dropping nothing: dashboard order is preserved because that is the
    /// order the paywall lists the plans in.
    init(offering: Offering) {
        self.init(
            offeringIdentifier: offering.identifier,
            plans: offering.availablePackages.map {
                PaywallPlan(package: $0, offeringIdentifier: offering.identifier)
            }
        )
    }
}

extension PaywallPlan {

    /// Reads the plan off the package that will actually be charged.
    ///
    /// The store is the only authority on the trial: a product reporting no introductory offer
    /// gets none, full stop. A config fallback used to fill that gap while App Store Connect was
    /// unconfigured, and once the real products existed it did exactly the harmful thing — put
    /// "7 days free" on the monthly plan, whose whole identifier says `notrial`.
    init(package: Package, offeringIdentifier: String) {
        let product = package.storeProduct
        let kind = Self.kind(for: package)

        self.init(
            id: Self.id(offeringIdentifier: offeringIdentifier, packageIdentifier: package.identifier),
            productIdentifier: product.productIdentifier,
            kind: kind,
            // For a billing plan product RevenueCat reports the commitment total here, which is
            // exactly what `PaywallPlan.priceString` documents — the monthly payment travels in
            // `installments`.
            priceString: product.localizedPriceString,
            price: product.price,
            // No `?? "month"` default, unlike the offer type this replaces. Defaulting a missing
            // period to "month" is what let a one-off purchase render as a subscription.
            periodTitle: product.subscriptionPeriod?.periodTitle,
            trialText: Self.trialText(for: product),
            installments: Self.installments(for: product)
            // No badge here: `PaywallCatalog` assigns every pill, because each one is a claim
            // about this plan relative to the others in the same offering.
        )
    }

    /// The installment shape, for a product RevenueCat resolved as a billing plan — an offering
    /// package whose product carries a plan identifier, like `smc_29.99_1y_7d_so:monthly`.
    /// Products with billing plans only exist on iOS 26.4+; on older systems RevenueCat never
    /// returns one, so the availability guard is a formality rather than a behaviour change.
    private static func installments(for product: StoreProduct) -> PaywallInstallments? {
        guard #available(iOS 26.4, *), let info = product.installmentsInfo else { return nil }
        return PaywallInstallments(
            count: info.commitmentInstallmentsCount,
            paymentPriceString: info.installmentBillingDisplayPrice
        )
    }

    /// `packageType` is the authority, because a non-consumable genuinely has no period and so
    /// cannot be classified from one. The product is only consulted when the dashboard used a
    /// custom package identifier.
    private static func kind(for package: Package) -> PaywallPlanKind {
        switch package.packageType {
        case .weekly: return .weekly
        case .monthly: return .monthly
        case .annual: return .annual
        case .lifetime: return .lifetime
        default:
            // No period at all means nothing recurs, so it is a one-off however the dashboard
            // named the package.
            guard let unit = package.storeProduct.subscriptionPeriod?.unit else { return .lifetime }
            switch unit {
            case .day, .week: return .weekly
            case .month: return .monthly
            case .year: return .annual
            // Same call `periodTitle` makes for a unit this SDK does not know: assume the
            // commonest recurrence rather than invent a fifth kind nothing can render.
            @unknown default: return .monthly
            }
        }
    }

    /// Bound once: `StoreProduct.introductoryDiscount` is computed, and allocates a fresh
    /// `StoreProductDiscount` on every access.
    private static func trialText(for product: StoreProduct) -> String? {
        // No introductory offer means no trial. No config fallback here, on purpose.
        guard let intro = product.introductoryDiscount else { return nil }
        // A non-free intro (pay-up-front or pay-as-you-go) is still an intro. Saying "free" over a
        // discounted-but-paid one would be a lie.
        return intro.paymentMode == .freeTrial ? trialText(for: intro.subscriptionPeriod) : nil
    }

    /// Normalised to the unit the store used, except that a one-week trial is spoken as "7 days" —
    /// which is what the App Store itself shows, and what the paywall copy has always said.
    private static func trialText(for period: SubscriptionPeriod) -> String {
        let value = period.value
        // Pluralized in the String Catalog (plural variation on the count), not here.
        switch period.unit {
        case .day:
            return String(localized: "\(value) days", comment: "Free trial length on the paywall")
        case .week:
            guard value != 1 else {
                return String(localized: "7 days", comment: "Length of the free trial, shown on the paywall")
            }
            return String(localized: "\(value) weeks", comment: "Free trial length on the paywall")
        case .month:
            return String(localized: "\(value) months", comment: "Free trial length on the paywall")
        case .year:
            return String(localized: "\(value) years", comment: "Free trial length on the paywall")
        @unknown default:
            return String(localized: "\(value) days", comment: "Free trial length on the paywall")
        }
    }
}

// MARK: - Period

extension SubscriptionPeriod {

    /// The recurrence as a noun to follow a slash. Lived on `PaywallViewModel` while the view model
    /// still spoke RevenueCat; it belongs beside the only remaining reader of it.
    var periodTitle: String {
        switch unit {
        case .day, .week: return String(localized: "week", comment: "Billing period noun after a slash, e.g. $4.99/week")
        case .month: return String(localized: "month", comment: "Billing period noun after a slash, e.g. $4.99/month")
        case .year: return String(localized: "year", comment: "Billing period noun after a slash, e.g. $29.99/year")
        @unknown default: return String(localized: "month", comment: "Billing period noun after a slash, e.g. $4.99/month")
        }
    }
}

