import Foundation
import RevenueCat

// MARK: - Offering Selection

/// Which offering a paywall surface sells.
///
/// A value rather than a bare identifier string, because the fallback rule — a named offering the
/// dashboard does not publish degrades to the default one — has to live in exactly one place. Two
/// screens now pick an offering, and a `String?` parameter is how they come to disagree about what
/// `nil` means.
enum PaywallOfferingSelector: Equatable, Sendable {
    /// The offering marked current on the RevenueCat dashboard. What the standard paywall and the
    /// Settings payramp sell.
    case current
    /// A named offering, falling back to `current` when the dashboard has no such offering — so a
    /// mis-set identifier sells the default plan rather than rendering an empty paywall with a
    /// dead button.
    case identifier(String)
}

// MARK: - Protocol

protocol SubscriptionServiceSupporting: Actor {
    /// The plans a surface should sell, resolved through `PaywallOfferingSelector`'s fallback
    /// rule. One method rather than a `currentOffering()` / `offering(identifier:)` pair, so the
    /// fallback cannot be re-derived at a call site. `nil` when nothing resolved — the store is
    /// unreachable, or the dashboard publishes nothing — and every screen must render a plan-less
    /// state rather than inventing one.
    ///
    /// Returns the app's own `PaywallCatalog` rather than a RevenueCat `Offering` because
    /// `Offering` reaches `StoreProduct`, whose only public initializers need a real StoreKit
    /// product. A protocol returning one has no mock implementation, which is why both paywalls
    /// on this app were drawn from hardcoded strings.
    func catalog(_ selector: PaywallOfferingSelector) async -> PaywallCatalog?
    /// Buys the plan a surface selected, by the id `catalog(_:)` handed out.
    ///
    /// An id rather than a `Package` is the whole seam: this file owns the id to package mapping
    /// it issued, so the RevenueCat type never leaves it. Throws `SubscriptionError.unknownPlan`
    /// when the id was not issued here — what a stale catalog looks like, and better than
    /// silently charging some other plan.
    func purchase(planID: PaywallPlan.ID) async throws
    func restorePurchases() async throws
    func resetEntitlements() async
    func prefetchOfferings() async
    /// Current Pro entitlement state, derived from the live RevenueCat customer info
    /// when reachable, else the cached value. Async so callers don't have to read the
    /// nonisolated-unsafe `static var hasPro` directly. Posted updates flow through
    /// `Notification.Name.subscriptionStateDidChange`.
    var hasProAsync: Bool { get async }
    /// Snapshot of the user's active Pro entitlement derived from the latest RC customer
    /// info. `nil` when the user has no active entitlement or the snapshot hasn't been
    /// refreshed yet.
    var entitlementSnapshot: EntitlementSnapshot? { get async }
}

// MARK: - Errors

enum SubscriptionError: Error, LocalizedError {
    /// The surface asked to buy a plan this service never issued, which is what a catalog held
    /// across a refresh looks like.
    case unknownPlan(PaywallPlan.ID)

    var errorDescription: String? {
        switch self {
        case .unknownPlan:
            "That plan is no longer available. Please reopen this screen and try again."
        }
    }
}

// MARK: - Notification

extension Notification.Name {
    /// Posted on the main queue whenever the user's Pro entitlement changes
    /// (restore, purchase completion, reset on sign-out).
    static let subscriptionStateDidChange = Notification.Name("IDKit.subscriptionStateDidChange")
}

// MARK: - Implementation

actor SubscriptionService: SubscriptionServiceSupporting {

    private var _hasPro: Bool = false

    private var _entitlementSnapshot: EntitlementSnapshot?
    private var purchasedProductIDs = Set<String>()
    private var cachedOfferings: Offerings?

    /// The packages `catalog(_:)` has handed out plan ids for, so `purchase(planID:)` can charge
    /// the right one. This map is why no RevenueCat type appears in the protocol.
    ///
    /// Cleared with `cachedOfferings`, never independently: a package resolved against last
    /// refresh's offerings is exactly the stale charge `unknownPlan` exists to prevent.
    private var packagesByPlanID: [PaywallPlan.ID: Package] = [:]

    /// Catalogs already derived from `cachedOfferings`, keyed by offering identifier.
    ///
    /// Deriving one is not free — per package a `kind` switch, `localizedPriceString`, and a fresh
    /// `subscriptionPeriod` and `introductoryDiscount` object, both of which RevenueCat computes
    /// and allocates on *every* access. `catalog(_:)` is not called once: Settings runs it on every
    /// return to the tab, and each paywall presentation runs it again. Same offering in means
    /// byte-identical catalog out, so derive it once per refresh.
    private var catalogsByOfferingID: [String: PaywallCatalog] = [:]

    // Holds the `customerInfoStream` listener task so the nonisolated `deinit` can cancel
    // it without crossing the actor boundary (same pattern as `LiveEntitlementSource.Box`).
    private let listenerBox = TaskBox()

    // MARK: - Init

    init() {
        // RevenueCat is the single source of truth for entitlements. It pushes a fresh
        // `CustomerInfo` on every change — purchase, renewal, expiration, and crucially
        // right after `Purchases.logIn(...)` aliases a signed-in account. Mirror each push
        // into the cache so `EntitlementSource` stays correct app-wide without a manual
        // refresh. `Purchases.configure` runs before this service is constructed.
        listenerBox.task = Task { [weak self] in
            guard Purchases.isConfigured else { return }
            for await info in Purchases.shared.customerInfoStream {
                await self?.ingest(info)
            }
        }
    }

    deinit {
        listenerBox.task?.cancel()
    }

    // MARK: - Purchase

    func purchase(planID: PaywallPlan.ID) async throws {
        guard let package = packagesByPlanID[planID] else {
            throw SubscriptionError.unknownPlan(planID)
        }
        let result = try await Purchases.shared.purchase(package: package)
        if result.userCancelled { return }
        try await updatePurchasedProducts()
    }

    // MARK: - Restore

    func restorePurchases() async throws {
        try await updatePurchasedProducts()
    }

    func resetEntitlements() async {
        _hasPro = false
        _entitlementSnapshot = nil
        purchasedProductIDs.removeAll()
        postSubscriptionStateDidChange()
    }

    var hasProAsync: Bool {
        get async {
            // Honor the documented contract: derive from live RevenueCat customer info when
            // reachable, falling back to the cached value offline. RC serves its local cache
            // immediately and refreshes from network only when stale, so this is cheap.
            // No notification is posted here — that would create a refresh→post→refresh loop
            // (the stream listener owns change notifications).
            if Purchases.isConfigured, let info = try? await Purchases.shared.customerInfo() {
                applyCustomerInfo(info)
            }
            return _hasPro
        }
    }

    var entitlementSnapshot: EntitlementSnapshot? {
        get async { _entitlementSnapshot }
    }

    // MARK: - Offerings

    func prefetchOfferings() async {
        do {
            cachedOfferings = try await Purchases.shared.offerings()
            // Both derived caches belong to the offerings they came from. Keeping either across a
            // refresh is how a screen comes to quote last fetch's price, or worse, charge last
            // fetch's package.
            catalogsByOfferingID.removeAll()
            packagesByPlanID.removeAll()
        } catch {
            // Silent fail
        }
    }

    /// Served entirely from `cachedOfferings`: `Purchases.offerings()` returns *every* offering in
    /// one call and `Offerings` resolves an identifier synchronously, so a named offering costs no
    /// extra round trip. That is what keeps `PaywallViewModel.loadCatalog()`'s no-spinner path
    /// true for the special offer screen too.
    func catalog(_ selector: PaywallOfferingSelector) async -> PaywallCatalog? {
        guard let offering = await offering(selector) else { return nil }
        if let cached = catalogsByOfferingID[offering.identifier] { return cached }

        let catalog = PaywallCatalog(offering: offering)
        catalogsByOfferingID[offering.identifier] = catalog

        // Record the mapping the ids in this catalog were minted from, so `purchase(planID:)` can
        // resolve one back. Zipped against the catalog rather than re-deriving the id string:
        // `PaywallCatalog.init(offering:)` is a 1:1 `map` over this same array, so the ids come
        // from the one function that mints them and cannot drift from what was handed out.
        //
        // Merged across offerings rather than replaced: the special offer screen and the Settings
        // payramp read different offerings, and whichever loaded second must not invalidate the
        // ids the other one is still showing. Staleness is bounded by `prefetchOfferings()`
        // clearing both caches together.
        for (plan, package) in zip(catalog.plans, offering.availablePackages) {
            packagesByPlanID[plan.id] = package
        }
        return catalog
    }

    private func offering(_ selector: PaywallOfferingSelector) async -> Offering? {
        if cachedOfferings == nil {
            await prefetchOfferings()
        }
        guard let offerings = cachedOfferings else { return nil }
        switch selector {
        case .current:
            return offerings.current
        case .identifier(let id):
            return offerings.offering(identifier: id) ?? offerings.current
        }
    }

    // MARK: - Private

    /// User-initiated refresh (purchase / restore). Always notifies observers.
    private func updatePurchasedProducts() async throws {
        let customerInfo = try await Purchases.shared.customerInfo()
        applyCustomerInfo(customerInfo)
        postSubscriptionStateDidChange()
    }

    /// Stream-driven update from `customerInfoStream`. Notifies observers only when the
    /// effective Pro state actually changed, to avoid redundant refresh churn.
    private func ingest(_ info: CustomerInfo) {
        let was = _hasPro
        applyCustomerInfo(info)
        if _hasPro != was {
            postSubscriptionStateDidChange()
        }
    }

    /// Mirror a RevenueCat `CustomerInfo` snapshot into the local cache. Does not notify.
    private func applyCustomerInfo(_ customerInfo: CustomerInfo) {
        purchasedProductIDs.removeAll()
        let activeEntitlements = customerInfo.entitlements.activeInCurrentEnvironment.values
        for entitlement in activeEntitlements where entitlement.isActive {
            purchasedProductIDs.insert(entitlement.productIdentifier)
        }
        _hasPro = !purchasedProductIDs.isEmpty
        if _hasPro, let entitlement = activeEntitlements.first(where: { $0.isActive }) {
            _entitlementSnapshot = EntitlementSnapshot.from(rc: entitlement)
        } else {
            _entitlementSnapshot = nil
        }
    }

    private nonisolated func postSubscriptionStateDidChange() {
        Task { @MainActor in
            NotificationCenter.default.post(name: .subscriptionStateDidChange, object: nil)
        }
    }
}

// MARK: - Task Box

/// Reference-typed cell holding the `customerInfoStream` listener task, so the actor's
/// nonisolated `deinit` can cancel it without touching actor-isolated state.
private final class TaskBox: @unchecked Sendable {
    var task: Task<Void, Never>?
}

// MARK: - RC Adapter

fileprivate extension EntitlementSnapshot {
    static func from(rc entitlement: EntitlementInfo) -> EntitlementSnapshot {
        let periodType: EntitlementPeriodType
        switch entitlement.periodType {
        case .normal: periodType = .normal
        case .trial: periodType = .trial
        case .intro: periodType = .intro
        @unknown default: periodType = .normal
        }
        return EntitlementSnapshot(
            status: EntitlementStatus.derive(
                isActive: entitlement.isActive,
                periodType: periodType,
                billingIssueDetectedAt: entitlement.billingIssueDetectedAt
            ),
            expirationDate: entitlement.expirationDate,
            productIdentifier: entitlement.productIdentifier
        )
    }
}

// MARK: - Mock

actor MockSubscriptionService: SubscriptionServiceSupporting {

    var hasProMock: Bool
    var entitlementSnapshotMock: EntitlementSnapshot?
    var shouldThrowOnRestore: Bool = false
    var shouldThrowOnPurchase: Bool = false
    var resetEntitlementsCallCount: Int = 0
    /// What `catalog(_:)` hands back, whatever was asked for. `nil` by default, which keeps two
    /// things true: every existing test gets the empty-catalog behaviour it was written against,
    /// and the release build's no-RevenueCat-key fallback (`Dependencies`) cannot start quoting
    /// fixture prices.
    var catalogToReturn: PaywallCatalog?
    /// Every selector `catalog(_:)` was asked for, in order. The seam that lets a test assert a
    /// screen sells the offering it advertises without needing a StoreKit fixture.
    private(set) var requestedSelectors: [PaywallOfferingSelector] = []
    /// Every plan id `purchase(planID:)` was asked to charge, in order. This is what was
    /// untestable before: no `Package` could be constructed, so nothing could assert that the CTA
    /// charges the plan the screen is displaying.
    private(set) var purchasedPlanIDs: [PaywallPlan.ID] = []

    init(hasProMock: Bool = false, catalog: PaywallCatalog? = nil) {
        self.hasProMock = hasProMock
        self.catalogToReturn = catalog
    }

    func setHasProMock(_ value: Bool) {
        hasProMock = value
    }

    func setEntitlementSnapshotMock(_ snapshot: EntitlementSnapshot?) {
        entitlementSnapshotMock = snapshot
    }

    func setShouldThrowOnRestore(_ value: Bool) {
        shouldThrowOnRestore = value
    }

    func setShouldThrowOnPurchase(_ value: Bool) {
        shouldThrowOnPurchase = value
    }

    func getResetEntitlementsCallCount() -> Int { resetEntitlementsCallCount }
    func getRequestedSelectors() -> [PaywallOfferingSelector] { requestedSelectors }
    func getPurchasedPlanIDs() -> [PaywallPlan.ID] { purchasedPlanIDs }

    func restorePurchases() async throws {
        if shouldThrowOnRestore { throw MockSubscriptionError.restoreFailed }
    }
    func resetEntitlements() async { resetEntitlementsCallCount += 1 }
    func purchase(planID: PaywallPlan.ID) async throws {
        purchasedPlanIDs.append(planID)
        if shouldThrowOnPurchase { throw MockSubscriptionError.purchaseFailed }
    }
    func prefetchOfferings() async {}
    func catalog(_ selector: PaywallOfferingSelector) async -> PaywallCatalog? {
        requestedSelectors.append(selector)
        return catalogToReturn
    }
    var hasProAsync: Bool {
        get async { hasProMock }
    }
    var entitlementSnapshot: EntitlementSnapshot? {
        get async { entitlementSnapshotMock }
    }
}

enum MockSubscriptionError: Error, LocalizedError {
    case restoreFailed
    case purchaseFailed

    var errorDescription: String? {
        switch self {
        case .restoreFailed: "MockSubscriptionError: restore failed (simulated)"
        case .purchaseFailed: "MockSubscriptionError: purchase failed (simulated)"
        }
    }
}

